import React, { useState } from 'react';
import { Routes, Route } from 'react-router-dom';
import { motion } from 'framer-motion';
import Sidebar from './layout/Sidebar';
import Header from './layout/Header';
import RFPWorkflow from './dashboard/RFPWorkflow';
import ProcessingQueue from './dashboard/ProcessingQueue';
import DocumentLibrary from './dashboard/DocumentLibrary';
import Analytics from './dashboard/Analytics';
import Settings from './dashboard/Settings';

const Dashboard: React.FC = () => {
  const [sidebarOpen, setSidebarOpen] = useState(true);

  return (
    <div className="flex h-screen bg-gray-50 dark:bg-gray-900 overflow-hidden">
      {/* Sidebar */}
      <Sidebar isOpen={sidebarOpen} onToggle={() => setSidebarOpen(!sidebarOpen)} />
      
      {/* Main Content */}
      <div className="flex-1 flex flex-col overflow-hidden">
        {/* Header */}
        <Header onMenuClick={() => setSidebarOpen(!sidebarOpen)} />
        
        {/* Main Content Area */}
        <main className="flex-1 overflow-auto p-6">
          <motion.div
            initial={{ opacity: 0, y: 20 }}
            animate={{ opacity: 1, y: 0 }}
            transition={{ duration: 0.3 }}
            className="max-w-7xl mx-auto"
          >
            <Routes>
              <Route path="/" element={<UploadCenter />} />
              <Route path="/upload" element={<UploadCenter />} />
              <Route path="/processing" element={<ProcessingQueue />} />
              <Route path="/library" element={<DocumentLibrary />} />
              <Route path="/analytics" element={<Analytics />} />
              <Route path="/settings" element={<Settings />} />
            </Routes>
          </motion.div>
        </main>
      </div>
    </div>
  );
};

export default Dashboard;
